// fetched. Both history paths stop early at the first transfer they already
// have, so a scope built from "the fresh ones" would silently never revisit a
// transfer whose item row did not exist at the time. Re-deriving from the whole
// ledger is a hash join on the indexed token_id that makes that class of miss
// unrepresentable.
//
// `sold_at IS NULL` does double duty: it makes the statement a no-op once a row
// is marked, and it pins sold_at to the first sale we ever observed rather than
// letting a later transfer overwrite it.
//
// `t.created_at >= i.created_at` is what makes a relist survivable. A token that
// sold and was relisted arrives as a new item_id for the same token, and
// ClearMarketplaceItemSold makes the new listing live again -- but its previous
// sale is still in the ledger, and without this guard the very next run would
// re-sell the item using a transfer that predates the listing. The invariant is
// that sold_at can never be earlier than created_at.
//
// RETURNING is what makes the count obtainable: without it there is no way to
// tell zero rows from a driver that reported none, and the sync panel would
// report "0 sold" on every run.
func (q *Queries) MarkItemsSold(ctx context.Context) ([]int32, error) {
	rows, err := q.db.QueryContext(ctx, markItemsSold)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int32{}
	for rows.Next() {
		var id int32
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateMarketplaceItem = `-- name: UpdateMarketplaceItem :one
UPDATE marketplace_items
SET token_id = $1,
    seller_id = $2,
    seller_name = $3::text,
    image_url = $4,
    name = $5,
    currency = COALESCE($6::text, currency),
    price = $7,
    grade_effect = $8,
    level = $9,
    enchant = $10,
    equipment_type = $11,
    created_at = $12,
    mint_time = COALESCE($13::timestamptz, mint_time)
WHERE id = $14
RETURNING id, token_id, seller_id, seller_name, image_url, name, currency, price,
          grade_effect, level, enchant, equipment_type, created_at, mint_time,
          sold_at, sold_price
`

type UpdateMarketplaceItemParams struct {
	TokenID       int32          `json:"token_id"`
	SellerID      string         `json:"seller_id"`
	SellerName    sql.NullString `json:"seller_name"`
	ImageUrl      string         `json:"image_url"`
	Name          string         `json:"name"`
	Currency      sql.NullString `json:"currency"`
	Price         float64        `json:"price"`
	GradeEffect   string         `json:"grade_effect"`
	Level         int32          `json:"level"`
	Enchant       int32          `json:"enchant"`
	EquipmentType string         `json:"equipment_type"`
	CreatedAt     time.Time      `json:"created_at"`
	MintTime      sql.NullTime   `json:"mint_time"`
	ID            int32          `json:"id"`
}

// currency falls back to the stored value rather than a literal default, and
// mint_time is written only when it parsed: an upstream payload that omitted or
// mangled mint_time must not blank a value we already hold.
//
// sold_at / sold_price are absent by design. This path is a re-scrape of a row
// we already had, and a re-scrape of a sold item must keep its sale.
func (q *Queries) UpdateMarketplaceItem(ctx context.Context, arg UpdateMarketplaceItemParams) (MarketplaceItem, error) {
	row := q.db.QueryRowContext(ctx, updateMarketplaceItem,
		arg.TokenID,
		arg.SellerID,
		arg.SellerName,
		arg.ImageUrl,
		arg.Name,
		arg.Currency,
		arg.Price,
		arg.GradeEffect,
		arg.Level,
		arg.Enchant,
		arg.EquipmentType,
		arg.CreatedAt,
		arg.MintTime,
		arg.ID,
	)
	var i MarketplaceItem
	err := row.Scan(
		&i.ID,
		&i.TokenID,
		&i.SellerID,
		&i.SellerName,
		&i.ImageUrl,
		&i.Name,
		&i.Currency,
		&i.Price,
		&i.GradeEffect,
		&i.Level,
		&i.Enchant,
		&i.EquipmentType,
		&i.CreatedAt,
		&i.MintTime,
		&i.SoldAt,
		&i.SoldPrice,
	)
	return i, err
}

const updateMarketplaceItemDetail = `-- name: UpdateMarketplaceItemDetail :one
UPDATE marketplace_item_detail
SET attributes = COALESCE($1::jsonb, attributes),
    datas = COALESCE($2::jsonb, datas),
    infos = COALESCE($3::jsonb, infos)
WHERE item_id = $4
RETURNING item_id, attributes, datas, infos
`

type UpdateMarketplaceItemDetailParams struct {
	Attributes pqtype.NullRawMessage `json:"attributes"`
	Datas      pqtype.NullRawMessage `json:"datas"`
	Infos      pqtype.NullRawMessage `json:"infos"`
	ItemID     int32                 `json:"item_id"`
}

// COALESCE on each blob: a null in the incoming payload preserves what is stored
// rather than blanking it.
func (q *Queries) UpdateMarketplaceItemDetail(ctx context.Context, arg UpdateMarketplaceItemDetailParams) (MarketplaceItemDetail, error) {
	row := q.db.QueryRowContext(ctx, updateMarketplaceItemDetail,
		arg.Attributes,
		arg.Datas,
		arg.Infos,
		arg.ItemID,
	)
	var i MarketplaceItemDetail
	err := row.Scan(
		&i.ItemID,
		&i.Attributes,
		&i.Datas,
		&i.Infos,
	)
	return i, err
}
